import{_ as i,l as d,o as e,c as l,v as t,p as s,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"树形 DP","description":"","frontmatter":{"title":"树形 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tree-dp.md","filePath":"cs/tree-dp.md","lastUpdated":1789023840000}'),h={name:"cs/tree-dp.md"};function _(D,a,m,u,P,f){const o=d("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="树形-dp" tabindex="-1">树形 DP <a class="header-anchor" href="#树形-dp" aria-label="Permalink to &quot;树形 DP&quot;">​</a></h1><div class="epigraph"><p>无环则子树先算完再合并到父亲；状态常是「选根或不选」「子树背包」，总 $O(n)$ 或 $O(n\\cdot\\text{容量})$。</p><footer>—— 据 CLRS 第 15 章最优子结构；树上 DP 为标准教材技法整理</footer></div><p>上一课<a href="/cs/bitmask-dp">状态压缩 DP</a>在指数子集上。树 \\(n\\) 可达 \\(10^5\\)，状态沿边无环。缺口是树形 DP：先 DFS 后序，把孩子 DP 合并。不重写状压。后课数位 DP 换十进制。与<a href="/cs/centroid-decomposition">点分治</a>分工：一个整棵最优，一个点对统计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立集：<code>dp[u][0/1]</code> 不选/选 \\(u\\)，孩子相应约束。树上背包：子树体积合并，注意循环方向防复用。换根是后课。本课固定根。</p><p>缺口是后序合并，不是生成树 MST。</p><h3 id="合并顺序与背包" tabindex="-1">合并顺序与背包 <a class="header-anchor" href="#合并顺序与背包" aria-label="Permalink to &quot;合并顺序与背包&quot;">​</a></h3><p>多个孩子做背包，\\(O(\\sum sz)\\) 要按子树大小分析，错误的 <code>for v in children for j backwards</code> 复杂度可能 \\(O(n^2)\\)。点名即可。</p><p><span class="marginnote">树独立集线性。树上背包复杂度有精细界。后课换根二次 DFS 把每个点当根。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DFS：先孩子后自己。状态设计使边只看父子。森林逐棵。</p>',11)),(e(),s(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%AD%A9%E5%AD%90%20dp%22%5D%20--%3E%20MER%5B%22%E5%90%88%E5%B9%B6%E5%88%B0%20u%22%5D%0A%20%20MER%20--%3E%20PAR%5B%22%E4%BA%A4%E7%BB%99%E7%88%B6%E4%BA%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>叶子边界明确。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>树的最优子结构：最优解在子树上的限制仍最优。与 DAG DP 同，树是特殊 DAG（定根后）。与 HLD：HLD 管路径查询，树 DP 管一次全局最优。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写换根、不写虚树。有环要先 SCC 或点双。后课默认：树上选/不选、子树背包用后序 DP。下一课数位 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后序合并孩子；无环是前提。</li><li>独立集线性；背包注意复杂度。</li><li>固定根；换根后课。</li><li>出处：CLRS 第 15 章；树 DP 标准技法。</li></ul>',7))])}const S=i(h,[["render",_]]);export{b as __pageData,S as default};
